def aggregate_scores(pairs):
    if not pairs:
        return {}

    result = {}
    order = []  # To keep track of first appearance order

    for name, score in pairs:
        if name not in result:
            result[name] = score
            order.append(name)
        else:
            result[name] = max(result[name], score)

    return {name: result[name] for name in order}

# Example usage:
pairs = [("Alice", 10), ("Bob", -5), ("Alice", 20), ("Charlie", 7)]
print(aggregate_scores(pairs)) 
# Output: {'Alice': 20, 'Bob': -5, 'Charlie': 7}
